// Check that the course created earlier is returned.
pm.test("Returns the created course", function () {
    pm.response.to.have.status(200);

    const course = pm.response.json();
    const savedCourseId = Number(pm.collectionVariables.get("courseId"));

    pm.expect(course.id).to.eql(savedCourseId);
    pm.expect(course.code).to.include("UAT-");
});

// Check that the course created earlier appears in the list.
pm.test("Course list includes the created course", function () {
    pm.response.to.have.status(200);

    const courses = pm.response.json();
    const savedCourseId = Number(pm.collectionVariables.get("courseId"));
    const createdCourse = courses.find(function (course) {
        return course.id === savedCourseId;
    });

    pm.expect(createdCourse).to.exist;
});

// Check that feedback was saved and its notification was recorded.
pm.test("Feedback is created and notification is recorded", function () {
    pm.response.to.have.status(201);

    const feedback = pm.response.json();
    pm.expect(feedback.student_id).to.eql(4);
    pm.expect(feedback.notification_recorded).to.eql(true);

    pm.collectionVariables.set("feedbackId", feedback.id);
});

// Check that the feedback created earlier appears in the list.
pm.test("Feedback list includes the created feedback", function () {
    pm.response.to.have.status(200);

    const feedbackItems = pm.response.json();
    const savedFeedbackId = Number(pm.collectionVariables.get("feedbackId"));
    const createdFeedback = feedbackItems.find(function (item) {
        return item.id === savedFeedbackId;
    });

    pm.expect(createdFeedback).to.exist;
});

// Check that an out of range rating is rejected.
pm.test("Invalid rating returns 400", function () {
    pm.response.to.have.status(400);
});

// Check that feedback for a missing student is rejected.
pm.test("Missing student returns 404", function () {
    pm.response.to.have.status(404);
});

// Check that the notification was saved.
pm.test("Notification is created", function () {
    pm.response.to.have.status(201);

    const notification = pm.response.json();
    pm.expect(notification.feedback_id).to.eql(
        Number(pm.collectionVariables.get("feedbackId"))
    );
    pm.expect(notification.recipient).to.eql("wiremu.pita@example.com");
});

// Check that Notification recorded the feedback event.
pm.test("Notification list includes the feedback notification", function () {
    pm.response.to.have.status(200);

    const notifications = pm.response.json();
    const savedFeedbackId = Number(pm.collectionVariables.get("feedbackId"));
    const feedbackNotification = notifications.find(function (item) {
        return item.feedback_id === savedFeedbackId;
    });

    pm.expect(feedbackNotification).to.exist;
});
